/**
 * Public surface of the `bencoder` stand-in, mirroring `bencoder.decode`.
 */

export { decode, decodeFirst } from './decoder.mjs';
export { Bytes, EMPTY_BYTES } from '../pytypes/bytestring.mjs';
export { PyDict } from '../pytypes/pydict.mjs';
export { pyRepr, pyStr, pyBytesRepr } from '../pytypes/repr.mjs';

/**
 * `Bytes` — an immutable byte sequence modelled on CPython's `bytes`.
 *
 * Representation: a plain JS string in which every code unit holds one byte
 * value (0..255). The source program only ever produces bytes via
 * `str.encode('ascii')`, so in practice every code unit is < 128. Keeping the
 * payload in a string lets us reuse JS string search/slice primitives and the
 * regular-expression engine directly, which is exactly what CPython's
 * `re.match(b'...', x)` does on the bytes side.
 */

export class Bytes {
  /** @param {string} raw one code unit per byte */
  constructor(raw) {
    /** @type {string} */
    this.raw = raw;
    Object.freeze(this);
  }

  /** `len(x)` */
  get length() {
    return this.raw.length;
  }

  /** `x[i]` — the integer byte value, or `undefined` when out of range. */
  byteAt(index) {
    if (index < 0 || index >= this.raw.length) return undefined;
    return this.raw.charCodeAt(index);
  }

  /** `x.startswith(prefix)` where `prefix` is given as a JS string. */
  startsWith(prefix) {
    return this.raw.startsWith(prefix);
  }

  /** `x[start:]` with Python's clamping semantics for non-negative `start`. */
  sliceFrom(start) {
    if (start <= 0) return this;
    if (start >= this.raw.length) return EMPTY_BYTES;
    return new Bytes(this.raw.slice(start));
  }

  /**
   * `x[start:start + count]`.
   *
   * `count` may be a bigint far beyond the sequence length — bencoded length
   * prefixes are arbitrary-precision integers and CPython simply clamps the
   * slice, which is why `b'9:value'` decodes to `b'value'`.
   */
  sliceCount(start, count) {
    const available = BigInt(Math.max(this.raw.length - start, 0));
    const take = count > available ? available : count;
    if (take <= 0n) return EMPTY_BYTES;
    return new Bytes(this.raw.slice(start, start + Number(take)));
  }

  /** `x[start + count:]`, clamped the same way as {@link sliceCount}. */
  sliceAfter(start, count) {
    const available = BigInt(Math.max(this.raw.length - start, 0));
    const take = count > available ? available : count;
    return this.sliceFrom(start + Number(take));
  }

  equals(other) {
    return other instanceof Bytes && other.raw === this.raw;
  }
}

export const EMPTY_BYTES = new Bytes('');

/** True when the byte is an ASCII decimal digit, i.e. `chr(b).isdigit()`. */
export function isAsciiDigitByte(byte) {
  return byte !== undefined && byte >= 0x30 && byte <= 0x39;
}

/**
 * `PyDict` — an insertion-ordered mapping with Python's key semantics.
 *
 * bencoder builds its result with `dict(zip(items[::2], items[1::2]))`, so:
 *   * key order follows first insertion,
 *   * re-assigning an existing key keeps its original position but replaces
 *     the value,
 *   * an unhashable key (a decoded list or dict) raises
 *     `TypeError: unhashable type: 'list'` / `'dict'`.
 */

import { Bytes } from './bytestring.mjs';
import { PyTypeError } from '../runtime/exceptions.mjs';

/** `type(value).__name__` for the values bencoder can produce. */
export function pyTypeName(value) {
  if (typeof value === 'bigint') return 'int';
  if (value instanceof Bytes) return 'bytes';
  if (Array.isArray(value)) return 'list';
  if (value instanceof PyDict) return 'dict';
  return 'object';
}

/**
 * A stable identity token standing in for `hash()` + `==`. `bytes` and `int`
 * keys never compare equal to one another, so tagging the namespace is enough.
 */
function hashKey(key) {
  if (typeof key === 'bigint') return `i:${key.toString(10)}`;
  if (key instanceof Bytes) return `b:${key.raw}`;
  throw new PyTypeError(`unhashable type: '${pyTypeName(key)}'`);
}

export class PyDict {
  constructor() {
    /** @type {Map<string, {key: unknown, value: unknown}>} */
    this._slots = new Map();
  }

  set(key, value) {
    const token = hashKey(key);
    const existing = this._slots.get(token);
    if (existing !== undefined) existing.value = value;
    else this._slots.set(token, { key, value });
  }

  get size() {
    return this._slots.size;
  }

  /** Key/value pairs in insertion order. */
  entries() {
    return [...this._slots.values()].map(({ key, value }) => [key, value]);
  }
}

/**
 * `dict(zip(keys, values))` where `items` alternates key, value, key, value…
 * A trailing key with no matching value is dropped, exactly like `zip`
 * truncating to the shorter sequence — this is why `d3:cowe` decodes to `{}`.
 */
export function pyDictFromFlatItems(items) {
  const result = new PyDict();
  const pairs = Math.floor(items.length / 2);
  for (let index = 0; index < pairs; index += 1) {
    result.set(items[index * 2], items[index * 2 + 1]);
  }
  return result;
}
